CREATE TABLE IF NOT EXISTS {{PUBLIC}}.case_definition (case_id STRING, public_number INT, slug STRING, seed BIGINT, generator_version INT, case_template_version INT, title STRING, hook STRING, datapoint_id STRING, entity_id STRING, period_id STRING, expected_value DECIMAL(18,2), observed_value DECIMAL(18,2), deviation DECIMAL(18,2), currency STRING, scale STRING, difficulty STRING, release_state STRING, sort_order INT, required_case_ids STRING, learning_objectives STRING, status STRING, created_at TIMESTAMP) USING DELTA
